import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var result = 0
        while (c > 32) {
            result = result * 10 + c - '0'.code
            c = readByte()
        }
        return result * sign
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val m = fs.nextInt()

    val state = IntArray(n)
    for (i in 0 until n) {
        state[i] = fs.nextInt()
    }

    val adjacency = Array(n) { ArrayList<Int>() }
    val reverseAdjacency = Array(n) { ArrayList<Int>() }

    repeat(m) {
        val u = fs.nextInt() - 1
        val v = fs.nextInt() - 1
        adjacency[u].add(v)
        reverseAdjacency[v].add(u)
    }

    val marked = BooleanArray(n)
    val answer = IntArray(n)
    val stack = IntArray(n)

    for (start in 0 until n) {
        if (!marked[start] && state[start] == 1) {
            var size = 0
            stack[size++] = start
            marked[start] = true
            answer[start]++

            while (size > 0) {
                val node = stack[--size]
                for (next in adjacency[node]) {
                    if (!marked[next]) {
                        marked[next] = true
                        answer[next]++
                        stack[size++] = next
                    }
                }
            }
        }
    }

    marked.fill(false)

    for (start in 0 until n) {
        if (!marked[start] && state[start] == 2) {
            var size = 0
            stack[size++] = start
            marked[start] = true
            answer[start]++

            while (size > 0) {
