        }

        var result = 0
        while (c > 32) {
            result = result * 10 + c - '0'.code
            c = readByte()
        }
        return result * sign
    }
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    val state = IntArray(n) { scanner.nextInt() }
    val head = IntArray(n) { -1 }
    val reverseHead = IntArray(n) { -1 }
    val to = IntArray(m)
    val next = IntArray(m)
    val reverseTo = IntArray(m)
    val reverseNext = IntArray(m)

    for (i in 0 until m) {
        val u = scanner.nextInt() - 1
        val v = scanner.nextInt() - 1

        to[i] = v
        next[i] = head[u]
        head[u] = i

        reverseTo[i] = u
        reverseNext[i] = reverseHead[v]
        reverseHead[v] = i
    }

    val marked = BooleanArray(n)
    val answer = IntArray(n)
    val stack = IntArray(n)

    fun dfsForward(start: Int) {
        var size = 0
        stack[size++] = start
        marked[start] = true

        while (size > 0) {
            val node = stack[--size]
            answer[node]++

            var edge = head[node]
            while (edge != -1) {
                val nextNode = to[edge]
                if (!marked[nextNode]) {
                    marked[nextNode] = true
                    stack[size++] = nextNode
                }
                edge = next[edge]
            }
        }
    }

    for (i in 0 until n) {
        if (!marked[i] && state[i] == 1) {
            dfsForward(i)
        }
    }

    marked.fill(false)

    fun dfsReverse(start: Int) {
        var size = 0
        stack[size++] = start
        marked[start] = true

        while (size > 0) {
            val node = stack[--size]
            answer[node]++

            if (state[node] == 1) continue

            var edge = reverseHead[node]
            while (edge != -1) {
                val nextNode = reverseTo[edge]
                if (!marked[nextNode]) {
                    marked[nextNode] = true
                    stack[size++] = nextNode
                }
                edge = reverseNext[edge]
            }
        }
    }

    for (i in 0 until n) {
